/*
 * Independently implemented public Kuaikan protocol adapter for Triomi.
 * Reference: keiyoushi/extensions-source, Apache-2.0,
 * dbf6c05d6a9520c60533f1626616263522bbe71a, Kuaikanmanhua.kt/Dto.kt.
 * Modified 2026-10-29: bounded data-only Nuxt parser (no eval), current
 * comics field/order, explicit restriction errors, validated HTTPS images.
 * No unlocking, login automation, request signing, or page-code execution.
 */
var KK_BASE = 'https://www.kuaikanmanhua.com';
function kkFail(message) { throw new Error('快看漫画：' + message); }
function kkPage(page) {
  if (!Number.isInteger(page) || page < 1 || page > 1000) kkFail('分页超出支持范围（1–1000）');
  return page;
}
function kkId(value) {
  var id = String(value == null ? '' : value);
  if (!/^[1-9][0-9]{0,14}$/.test(id)) kkFail('作品或章节编号无效');
  return id;
}
function kkUrlId(url, kind, fallback) {
  var pattern = kind === 'topic'
    ? /^https:\/\/www\.kuaikanmanhua\.com\/web\/topic\/([1-9][0-9]{0,14})\/?$/
    : /^https:\/\/www\.kuaikanmanhua\.com\/web(?:s\/comic-next|\/comic)\/([1-9][0-9]{0,14})\/?$/;
  var match = String(url || '').match(pattern);
  if (!match) kkFail('仅支持官网作品或章节地址');
  var id = kkId(match[1]);
  if (fallback != null && kkId(fallback) !== id) kkFail('请求编号与条目不匹配');
  return id;
}
function kkImage(value) {
  if (typeof value !== 'string' || value.length > 4096 ||
      !/^https:\/\/(?:[a-z0-9-]+\.)*(?:kkmh\.com|v3mh\.com|kuaikanmanhua\.com)\/[^^\s\\]*$/i.test(value))
    kkFail('图片地址无效或不是官网 HTTPS 图片域名');
  return value;
}
function kkMessage(value) {
  return String(value && (value.message || value.msg || value.error_message) || '').replace(/[\r\n<>]/g, ' ').slice(0, 180);
}
function kkEnvelope(value, label) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) kkFail(label + '数据结构不可识别');
  if (value.code != null && Number(value.code) !== 200)
    kkFail(label + '返回代码 ' + String(value.code) + '：' + kkMessage(value) + '；请在官网确认登录、付费、App 或访问限制，不提供解锁');
  return value;
}
async function kkFetch(url) {
  var response = await triomi.fetch(url);
  if (response.status !== 200) kkFail('HTTP ' + response.status + '；请在官网确认访问限制');
  if (typeof response.body !== 'string' || response.body.length > 8000000) kkFail('响应为空或超过安全大小限制');
  return response.body;
}
// This grammar reads literals and devalue's simple alias mutations as data.
// It cannot execute calls, getters, operators, functions, loops or page code.
function KkRef(name) { this.name = name; }
function KkDataParser(text) {
  if (text.length > 8000000) kkFail('页面数据超过安全大小限制');
  this.s = text; this.i = 0; this.nodes = 0;
}
KkDataParser.prototype.space = function() {
  while (this.i < this.s.length && /\s/.test(this.s.charAt(this.i))) this.i++;
};
KkDataParser.prototype.take = function(token) {
  this.space();
  if (this.s.slice(this.i, this.i + token.length) !== token) kkFail('页面数据不是受支持的安全字面量');
  this.i += token.length;
};
KkDataParser.prototype.identifier = function() {
  this.space();
  var start = this.i;
  if (!/[A-Za-z_$]/.test(this.s.charAt(this.i)) || this.i >= this.s.length) kkFail('页面数据标识符无效');
  this.i++;
  while (this.i < this.s.length && /[A-Za-z0-9_$]/.test(this.s.charAt(this.i))) this.i++;
  return this.s.slice(start, this.i);
};
function kkKey(key) {
  if (key === '__proto__' || key === 'constructor' || key === 'prototype') kkFail('页面数据包含不安全属性');
  return key;
}
KkDataParser.prototype.string = function() {
  var start = this.i++;
  while (this.i < this.s.length) {
    var c = this.s.charAt(this.i++);
    if (c === '\\') this.i++;
    else if (c === '"') {
      try { return JSON.parse(this.s.slice(start, this.i)); }
      catch (_) { kkFail('页面字符串字面量无效'); }
    }
  }
  kkFail('页面字符串不完整');
};
KkDataParser.prototype.value = function(refs, depth) {
  this.space();
  if (++this.nodes > 250000 || depth > 80 || this.i >= this.s.length) kkFail('页面数据超出解析限制或不完整');
  var c = this.s.charAt(this.i), result, key;
  if (c === '"') return this.string();
  if (c === '{') {
    this.i++; this.space(); result = Object.create(null);
    while (this.s.charAt(this.i) !== '}') {
      key = kkKey(this.s.charAt(this.i) === '"' ? this.string() : this.identifier());
      if (Object.prototype.hasOwnProperty.call(result, key)) kkFail('页面数据包含重复属性');
      this.take(':'); result[key] = this.value(refs, depth + 1); this.space();
      if (this.s.charAt(this.i) !== ',') break;
      this.i++; this.space();
    }
    this.take('}'); return result;
  }
  if (c === '[') {
    this.i++; this.space(); result = [];
    while (this.s.charAt(this.i) !== ']') {
      result.push(this.value(refs, depth + 1)); this.space();
      if (this.s.charAt(this.i) !== ',') break;
      this.i++; this.space();
    }
    this.take(']'); return result;
  }
  if (c === '-' || /[0-9]/.test(c)) {
    var start = this.i;
    while (this.i < this.s.length && /[0-9eE+.\-]/.test(this.s.charAt(this.i))) this.i++;
    var raw = this.s.slice(start, this.i);
    if (!/^-?(?:0|[1-9][0-9]*)(?:\.[0-9]+)?(?:[eE][+\-]?[0-9]+)?$/.test(raw) || !Number.isFinite(Number(raw))) kkFail('页面数值无效');
    return Number(raw);
  }
  var name = this.identifier();
  if (name === 'true') return true;
  if (name === 'false') return false;
  if (name === 'null') return null;
  if (name === 'void') { this.take('0'); return null; }
  if (name === 'Array') {
    this.take('('); var count = this.value(false, depth + 1); this.take(')');
    if (!Number.isInteger(count) || count < 0 || count > 10000) kkFail('页面数组超出安全限制');
    result = []; for (var n = 0; n < count; n++) result.push(null);
    return result;
  }
  if (refs) return new KkRef(name);
  kkFail('页面数据包含不支持的表达式');
};
function kkNuxt(html) {
  var re = /<script\b[^>]*>([\s\S]*?)<\/script\s*>/gi, match, script = null, count = 0;
  while ((match = re.exec(html)) !== null) {
    if (++count > 300) kkFail('页面脚本数量超出安全限制');
    if (/^\s*window\.__NUXT__\s*=/.test(match[1])) {
      if (script !== null) kkFail('页面包含重复数据定义');
      script = match[1];
    }
  }
  if (script === null) kkFail('页面数据缺失；可能遇到验证、登录、App 或访问限制，请在官网检查');
  var p = new KkDataParser(script), names = [], actions = [], args = [], nameSet = Object.create(null);
  p.take('window.__NUXT__'); p.take('='); p.take('('); p.take('function'); p.take('('); p.space();
  while (p.s.charAt(p.i) !== ')') {
    var name = kkKey(p.identifier());
    if (nameSet[name] || names.length >= 10000) kkFail('页面数据参数无效');
    nameSet[name] = true; names.push(name); p.space();
    if (p.s.charAt(p.i) !== ',') break;
    p.i++; p.space();
  }
  p.take(')'); p.take('{'); p.space();
  while (p.s.slice(p.i, p.i + 6) !== 'return') {
    if (actions.length >= 10000) kkFail('页面别名数量超出安全限制');
    var target = kkKey(p.identifier()), key;
    p.space();
    if (p.s.charAt(p.i) === '.') { p.i++; key = kkKey(p.identifier()); }
    else { p.take('['); key = p.value(false, 0); p.take(']'); }
    p.take('='); var value = p.value(true, 0); p.take(';'); p.space();
    actions.push({target:target, key:kkKey(String(key)), value:value});
  }
  p.take('return'); var root = p.value(true, 0); p.space();
  if (p.s.charAt(p.i) === ';') p.i++;
  p.take('}'); p.take('('); p.space();
  while (p.s.charAt(p.i) !== ')') {
    args.push(p.value(false, 0)); p.space();
    if (args.length > names.length) kkFail('页面参数数量不匹配');
    if (p.s.charAt(p.i) !== ',') break;
    p.i++; p.space();
  }
  p.take(')'); p.take(')'); p.space();
  if (p.s.charAt(p.i) === ';') p.i++;
  p.space();
  if (p.i !== p.s.length || args.length !== names.length) kkFail('页面包含额外程序或参数不匹配');
  var env = Object.create(null);
  for (var j = 0; j < names.length; j++) env[names[j]] = args[j];
  function reference(v) {
    if (!(v instanceof KkRef)) return v;
    if (!Object.prototype.hasOwnProperty.call(env, v.name)) kkFail('页面引用未声明参数');
    return env[v.name];
  }
  for (var k = 0; k < actions.length; k++) {
    var action = actions[k], object = reference(new KkRef(action.target));
    if (!object || typeof object !== 'object') kkFail('页面别名目标不是数据容器');
    if (Array.isArray(object) && (!/^(0|[1-9][0-9]*)$/.test(action.key) || Number(action.key) >= object.length)) kkFail('页面数组别名越界');
    object[action.key] = reference(action.value);
  }
  var visits = 0;
  function resolve(v, depth, stack) {
    v = reference(v);
    if (++visits > 350000 || depth > 80) kkFail('页面数据超出解析限制');
    if (!v || typeof v !== 'object') return v;
    if (stack.indexOf(v) !== -1) kkFail('页面数据包含循环引用');
    stack.push(v);
    var out = Array.isArray(v) ? [] : Object.create(null), keys = Object.keys(v);
    for (var n = 0; n < keys.length; n++) out[keys[n]] = resolve(v[keys[n]], depth + 1, stack);
    stack.pop(); return out;
  }
  var payload = resolve(root, 0, []);
  if (!payload || !Array.isArray(payload.data) || !payload.data[0]) kkFail('页面数据结构不可识别');
  return payload.data[0];
}
function kkItem(row) {
  if (!row || typeof row.title !== 'string' || !row.title.trim()) kkFail('作品列表字段不完整');
  var id = kkId(row.id);
  return {remoteId:id, title:row.title, url:KK_BASE + '/web/topic/' + id,
    coverUrl:kkImage(row.vertical_image_url), author:row.author_name || undefined};
}
function kkRows(rows) {
  if (!Array.isArray(rows) || rows.length > 1000) kkFail('作品列表结构不可识别');
  return rows.map(kkItem);
}
async function discover(url, page) {
  kkPage(page);
  var sort = /[?&]sort=3(?:&|$)/.test(String(url)) ? '3' : '2';
  var data = kkNuxt(await kkFetch(KK_BASE + '/tag/0?region=1&pays=0&state=0&sort=' + sort + '&page=' + page));
  if (data.res) kkEnvelope(data.res, '列表');
  if (data.page != null && Number(data.page) !== page) return [];
  return kkRows(data.dataList);
}
async function search(keyword, page) {
  kkPage(page);
  var query = String(keyword || '').trim();
  if (!query) return [];
  if (query.length > 200) kkFail('搜索文字过长');
  var body = await kkFetch('https://api.kkmh.com/v1/search/topic?q=' + encodeURIComponent(query) + '&since=' + ((page - 1) * 10) + '&size=10');
  var result;
  try { result = JSON.parse(body); } catch (_) { kkFail('搜索未返回 JSON；可能遇到验证或访问限制'); }
  kkEnvelope(result, '搜索');
  if (!result.data || !Object.prototype.hasOwnProperty.call(result.data, 'hit')) kkFail('搜索数据缺失；请在官网检查访问限制');
  return kkRows(result.data.hit);
}
function kkLocked(info) {
  return info.locked === true || info.need_vip === true ||
    (info.is_pay_comic === true && info.is_free !== true && info.has_bought !== true) ||
    (info.locked_code != null && Number(info.locked_code) !== 200);
}
async function detail(url, item) {
  var id = kkUrlId(url, 'topic', item && item.remoteId), data = kkNuxt(await kkFetch(KK_BASE + '/web/topic/' + id));
  if (data.res) kkEnvelope(data.res, '作品');
  if (data.code != null) kkEnvelope(data, '作品');
  var info = data.topicInfo || (data.res && data.res.data && data.res.data.topic_info);
  if (!info || kkId(info.id == null ? id : info.id) !== id) kkFail('作品详情编号不匹配');
  var result = kkItem(Object.assign({}, info, {id:id}));
  result.description = typeof info.description === 'string' ? info.description : '';
  result.author = info.user && info.user.nickname || '';
  result.status = info.update_status || '';
  result.tags = Array.isArray(info.tags) ? info.tags.filter(function(t) { return typeof t === 'string'; }) : [];
  var rows, reverse = false;
  if (Array.isArray(data.comics)) rows = data.comics;
  else if (Array.isArray(data.comicList)) { rows = data.comicList; reverse = true; }
  else rows = data.res && data.res.data && data.res.data.topic_info && data.res.data.topic_info.comics;
  if (!Array.isArray(rows) || !rows.length || rows.length > 10000) kkFail('章节目录缺失或不可识别；请在官网检查作品限制');
  if (Number.isInteger(info.comics_count) && info.comics_count !== rows.length) kkFail('官网目录不完整；不返回截断章节');
  if (reverse) rows = rows.slice().reverse();
  var seen = Object.create(null), chapters = rows.map(function(row) {
    var cid = kkId(row.id);
    if (seen[cid] || typeof row.title !== 'string' || !row.title.trim()) kkFail('章节目录存在重复编号或缺失标题');
    seen[cid] = true;
    return {remoteId:cid, title:row.title, url:KK_BASE + '/web/comic/' + cid, locked:kkLocked(row)};
  });
  return {item:result, chapters:chapters};
}
async function content(url, chapter) {
  var id = kkUrlId(url, 'comic', chapter && chapter.remoteId), data = kkNuxt(await kkFetch(KK_BASE + '/webs/comic-next/' + id));
  var res = kkEnvelope(data.res, '阅读器');
  if (data.comic_id != null && kkId(data.comic_id) !== id) kkFail('阅读器章节编号不匹配');
  var info = res.data && res.data.comic_info;
  if (!info || kkId(info.id) !== id) kkFail('阅读器数据缺失或章节编号不匹配');
  if ((data.status != null && Number(data.status) !== 200) || kkLocked(info) || (data.comicInfo && kkLocked(data.comicInfo)))
    kkFail('章节受限（' + String(data.status || info.locked_code || 'locked') + '）' + kkMessage(res) + '；请在官网确认付费、登录或 App 限制，不提供解锁');
  var images = info.comic_images;
  if (!Array.isArray(images) || !images.length || images.length > 2000) kkFail('阅读图片缺失；可能需要付费、登录或 App，不提供解锁');
  return {images:images.map(function(image) {
    if (!image || typeof image !== 'object') kkFail('阅读图片字段不完整');
    return kkImage(image.url1280 || image.url);
  })};
}
